-- # Lernfeld 5: Cyberphysische Systeme > ## Softwareplanung > - Anforderungen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Anforderungen ohne Beteiligung der Stakeholder vollständig erfasst werden?', 2, '[{"text": "Nein", "correct": true, "because": "Stakeholder definieren Bedürfnisse"}, {"text": "Ja", "correct": false, "because": "Ohne Input fehlt Kontext"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind funktionale Anforderungen wichtiger als nicht-funktionale Anforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Beide sind für Erfolg essenziell"}, {"text": "Ja", "correct": false, "because": "Nicht-funktionale ebenso kritisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Software ohne klare Anforderungen erfolgreich entwickelt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Unklarheit führt zu Fehlern"}, {"text": "Ja", "correct": false, "because": "Ziele müssen definiert sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, Anforderungen während der Entwicklungsphase zu ändern?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität ist oft nötig"}, {"text": "Nein", "correct": false, "because": "Änderungen sind machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Anforderungen vor Projektstart vollständig dokumentiert sein?', 2, '[{"text": "Nein", "correct": true, "because": "Iterative Modelle erlauben Anpassung"}, {"text": "Ja", "correct": false, "because": "Dynamik ist möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Art von Anforderung beschreibt, was die Software tun soll?', 2, '[{"text": "Funktionale Anforderung", "correct": true, "because": "Definiert Funktionen"}, {"text": "Nicht-funktionale Anforderung", "correct": false, "because": "Fokussiert Qualität"}, {"text": "Technische Anforderung", "correct": false, "because": "Umsetzungsdetail"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft ist für eine nicht-funktionale Anforderung am typischsten?', 3, '[{"text": "Leistung", "correct": true, "because": "Beschreibt Qualitätsaspekte"}, {"text": "Benutzerinteraktion", "correct": false, "because": "Funktionaler Aspekt"}, {"text": "Datenverarbeitung", "correct": false, "because": "Funktionale Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft am besten, Anforderungen von Kunden zu erheben?', 2, '[{"text": "Interviews", "correct": true, "because": "Direkte Bedürfnisse erfragt"}, {"text": "Code-Reviews", "correct": false, "because": "Spätere Phase"}, {"text": "Prototyping", "correct": false, "because": "Validierung, nicht Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium macht eine Anforderung messbar?', 2, '[{"text": "Spezifische Metriken", "correct": true, "because": "Erlaubt Überprüfung"}, {"text": "Vage Formulierung", "correct": false, "because": "Unklarheit vermeiden"}, {"text": "Kundenwunsch", "correct": false, "because": "Nicht automatisch messbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die größte Gefahr bei unklaren Anforderungen?', 2, '[{"text": "Missverständnisse", "correct": true, "because": "Führt zu falscher Umsetzung"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten steigen oft"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Verzögerungen wahrscheinlicher"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Typen von Anforderungen gibt es in der Softwareplanung?', 4, '[{"text": "Funktionale", "correct": true, "because": "Beschreiben Funktionen"}, {"text": "Nicht-funktionale", "correct": true, "because": "Beschreiben Qualität"}, {"text": "Finanzielle", "correct": false, "because": "Projektmanagement"}, {"text": "Technische", "correct": true, "because": "Umsetzungsdetails"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sollten Anforderungen aufweisen?', 3, '[{"text": "Klarheit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Messbarkeit", "correct": true, "because": "Überprüfung ermöglicht"}, {"text": "Unbestimmtheit", "correct": false, "because": "Gegenteil nötig"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Aspekte abdecken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Erfassung von Anforderungen?', 3, '[{"text": "Workshops", "correct": true, "because": "Kollaborative Erhebung"}, {"text": "Fragebögen", "correct": true, "because": "Strukturierte Rückmeldung"}, {"text": "Code-Tests", "correct": false, "because": "Spätere Phase"}, {"text": "Beobachtung", "correct": true, "because": "Nutzerbedarf erkennen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch schlecht definierte Anforderungen?', 4, '[{"text": "Scope Creep", "correct": true, "because": "Zielverschiebung"}, {"text": "Verzögerungen", "correct": true, "because": "Klarstellung nötig"}, {"text": "Perfekte Umsetzung", "correct": false, "because": "Unwahrscheinlich"}, {"text": "Kostenüberschreitung", "correct": true, "because": "Nacharbeit teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu nicht-funktionalen Anforderungen?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Qualitätsmerkmal"}, {"text": "Benutzbarkeit", "correct": true, "because": "Nutzererlebnis"}, {"text": "Datenbankstruktur", "correct": false, "because": "Technischer Aspekt"}, {"text": "Skalierbarkeit", "correct": true, "because": "Leistungsmerkmal"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Funktionale Anforderungen beschreiben Systemleistung. b) Stakeholder müssen Anforderungen genehmigen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Funktional beschreibt Funktion, Genehmigung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anforderungen ändern sich nie nach Projektstart. b) Nicht-funktionale Anforderungen beeinflussen die Benutzererfahrung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Änderungen möglich, Benutzererfahrung relevant"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unklare Anforderungen führen zu Projektverzögerungen. b) Alle Anforderungen müssen technisch umsetzbar sein.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Unklarheit verzögert, Umsetzbarkeit essenziell"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Anforderungen sollten vor der Implementierung feststehen. b) Workshops sind die einzige Methode zur Anforderungserhebung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Festlegung ideal, Methoden vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nicht-funktionale Anforderungen sind optional. b) Klare Anforderungen reduzieren Entwicklungskosten.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Nicht-funktional nötig, Klarheit spart"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

